return ['domain'=>'publishpress-statuses-pro% 100 >= 3 && n % 100 <= 10 ? 3 : n % 100 >= 11 ? 4 : 5);% 100 >= 3 && n % 100 <= 10 ? 3: n % 100 >= 11 ? 4 : 5);&& n%100<=10 ? 3: n%100>=11 ? 4 : 5);','plural-forms'=>'nplurals=6; plural=(n == 0 ? 0 : n == 1 ? 1 : n == 2 ? 2 : n % 100 >= 3 && n % 100 <= 10 ? 3 : n % 100 >= 11 ? 4 : 5);','language'=>'ar','project-id-version'=>'PublishPress Statuses Pro 1.3.1-beta','pot-creation-date'=>'2026-04-29T19:59:23+00:00','po-revision-date'=>'2026-09-02 21:48+0000','x-generator'=>'WP-CLI 2.13.0-alpha','messages'=>['PublishPress Statuses Pro'=>'PublishPress Statuses Pro','https://publishpress.com/statuses'=>'https://publishpress.com/statuses','Manage and create post statuses to customize your editorial workflow'=>'إدارة وإنشاء حالات المنشورات لتخصيص سير العمل التحريري الخاص بك','PublishPress'=>'PublishPress','https://publishpress.com/'=>'https://publishpress.com/','New Revision created'=>'تم إنشاء مراجعة جديدة','Revision is submitted'=>'تم تقديم المراجعة','Revision deferred or rejected'=>'تم تأجيل المراجعة أو رفضها','Revision is scheduled'=>'تم جدولة المراجعة','Scheduled Revision published'=>'تم نشر المراجعة المجدولة','Post status changed'=>'تم تغيير حالة المنشور','Post deferred or rejected'=>'تم تأجيل المنشور أو رفضه','Revision Status'=>'حالة المراجعة','Drop any status here to include it in main workflow for post revisions.'=>'ضع أي حالة هنا لتضمينها في سير العمل الرئيسي للمراجعات.','Drop any status here to make it manually selectable outside the main revision workflow.'=>'ضع أي حالة هنا لجعلها قابلة للاختيار يدوياً خارج سير العمل الرئيسي للمراجعة.','Add New Visibility Status'=>'إضافة حالة رؤية جديدة','Add New Revision Status'=>'إضافة حالة مراجعة جديدة','This status can be assigned to a post as a different form of Private Publication with its own capability requirements.'=>'يمكن تعيين هذه الحالة لمنشور كسمة مختلفة من النشر الخاص مع متطلبات القدرة الخاصة بها.','This status can be assigned to revisions of published posts.'=>'يمكن تعيين هذه الحالة لمراجعات المنشورات المنشورة.','Revision Statuses'=>'حالات المراجعة','Main Revision Workflow:'=>'سير العمل الرئيسي للمراجعة:','Alternate Revision Workflow:'=>'سير العمل البديل للمراجعة:','Revision Deferred'=>'تم تأجيل المراجعة','Defer'=>'تأجيل','Revision has been deferred for future consideration.'=>'تم تأجيل المراجعة للنظر فيها في المستقبل.','Revision Needs Work'=>'المراجعة تحتاج إلى عمل','Set to Needs Work'=>'تعيين إلى يحتاج إلى عمل','Revision needs work before further review.'=>'تحتاج المراجعة إلى عمل قبل المراجعة الإضافية.','Change Deferred'=>'تغيير مؤجل','Change has been deferred for future consideration.'=>'تم تأجيل التغيير للنظر فيه في المستقبل.','Change Needs Work'=>'تغيير يحتاج إلى عمل','Change needs work before further review.'=>'يحتاج التغيير إلى عمل قبل المراجعة الإضافية.','To use PublishPress Statuses, please upgrade PublishPress Planner to version %s or higher.'=>'لاستخدام PublishPress Statuses، يرجى ترقية PublishPress Planner إلى الإصدار %s أو أعلى.','To use PublishPress Statuses, please upgrade PublishPress Permissions Pro to version %s or higher.'=>'لاستخدام PublishPress Statuses، يرجى ترقية PublishPress Permissions Pro إلى الإصدار %s أو أعلى.','To use PublishPress Statuses, please upgrade PublishPress Capabilities Pro to version %s or higher.'=>'لاستخدام PublishPress Statuses، يرجى ترقية PublishPress Capabilities Pro إلى الإصدار %s أو أعلى.','%sYour license key has expired%s. For continued priority support, %splease renew%s.'=>'%sلقد انتهت صلاحية مفتاح الترخيص الخاص بك%s. لمتابعة الدعم ذي الأولوية، %sيرجى التجديد%s.','%sYour license key will expire today%s. For updates and priority support, %splease renew%s.'=>'%sستنتهي صلاحية مفتاح الترخيص الخاص بك اليوم%s. للحصول على التحديثات والدعم ذي الأولوية، %sيرجى التجديد%s.','%sYour license key (for plugin updates) will expire in %d days%s. For updates and priority support, %splease renew%s.'=>'%sستنتهي صلاحية مفتاح الترخيص الخاص بك (لتحديثات الإضافات) في %d يوماً%s. للحصول على التحديثات والدعم ذي الأولوية، %sيرجى التجديد%s.','For updates to PublishPress Statuses Pro, activate your %sPublishPress license key%s.'=>'لتحديثات PublishPress Statuses Pro، قم بتنشيط %sمفتاح ترخيص PublishPress الخاص بك%s.','Deactivate Key'=>'إلغاء تنشيط المفتاح','Key Expired'=>'المفتاح منتهي الصلاحية','Activate Key'=>'تنشيط المفتاح','Key Activated'=>'تم تنشيط المفتاح','%1$s PublishPress Statuses Pro %2$s %3$s'=>'%1$s PublishPress Statuses Pro %2$s %3$s','%1$sInstalled Version:%2$s'=>'%1$sالإصدار المثبت:%2$s','view %s&nbsp;details'=>'عرض %s&nbsp;التفاصيل','update check / install'=>'تحقق من التحديثات / التثبيت','Connecting to publishpress.com server...'=>'جاري الاتصال بخادم publishpress.com...','The request could not be processed due to a connection failure.'=>'لم يكن بالإمكان معالجة الطلب بسبب فشل في الاتصال.','Please enter the license key shown on your order receipt.'=>'يرجى إدخال مفتاح الترخيص الموضح في إيصال الطلب الخاص بك.','An unidentified error occurred.'=>'حدث خطأ غير محدد.','The key has been deactivated.'=>'تم إلغاء تنشيط المفتاح.','The key has been activated.'=>'تم تنشيط المفتاح.','The key has expired.'=>'انتهت صلاحية المفتاح.','The key is invalid.'=>'المفتاح غير صالح.','An unknown activation error occurred.'=>'حدث خطأ غير معروف في التنشيط.','The key provided is not valid. Please double-check your entry.'=>'المفتاح المقدم غير صالح. يرجى التحقق من إدخالك مرة أخرى.','This site is not valid to activate the key.'=>'هذا الموقع غير صالح لتنشيط المفتاح.','The key provided could not be validated by publishpress.com.'=>'لم يتمكن publishpress.com من التحقق من صحة المفتاح المقدم.','The key provided is already active on another site.'=>'المفتاح المقدم مفعل بالفعل على موقع آخر.','The key has already been activated on the allowed number of sites.'=>'تم تنشيط المفتاح بالفعل على العدد المسموح به من المواقع.','An unknown deactivation error occurred.'=>'حدث خطأ غير معروف في إلغاء التنشيط.','Unable to deactivate because the provided key is not valid.'=>'لا يمكن إلغاء التنشيط لأن المفتاح المقدم غير صالح.','This site is not valid to deactivate the key.'=>'هذا الموقع غير صالح لإلغاء تنشيط المفتاح.','The key provided is not active on the specified site.'=>'المفتاح المقدم غير مفعل على الموقع المحدد.','%s: '=>'%s: ','Custom %s: '=>'مخصص %s: ','Main Workflow: '=>'سير العمل الرئيسي: ','Visibility: '=>'الرؤية: ','Revision: '=>'المراجعة: ','force visibility of all sub%s'=>'فرض رؤية جميع الفرعية %s','Visibility forced to %1$s'=>'تم فرض الرؤية على %1$s','%s, Sticky'=>'%s، لاصق','mirror selection to %1$s sub%2$s%3$s'=>'نسخ التحديد إلى %1$s فرعي %2$s %3$s','(manual)'=>'(يدوي)','visibility of subpages set individually'=>'تم تعيين رؤية الصفحات الفرعية بشكل فردي','Your %1$s was successfully submitted, but you cannot make further edits at this time. The current status of the %1$s is %2$s.'=>'تم تقديم %1$s الخاص بك بنجاح، لكن لا يمكنك إجراء تعديلات إضافية في هذا الوقت. الحالة الحالية لـ %1$s هي %2$s.','Subpages'=>'الصفحات الفرعية','Force visibility of sub-%s'=>'فرض رؤية الفرعي - %s','apply to existing sub-%s'=>'تطبيق على الفرعي الموجود - %s','Manual Visibility selection'=>'اختيار الرؤية اليدوية','No Visibility Restrictions'=>'لا قيود على الرؤية','Status may also be altered by category or term'=>'يمكن أيضًا تغيير الحالة حسب الفئة أو المصطلح','Private'=>'خاص','Visibility Statuses'=>'حالات الرؤية','Visibility locked'=>'الرؤية مقفلة','Subpage Visibility'=>'رؤية الصفحة الفرعية','Force Visibility'=>'فرض الرؤية','Type-specific Supplemental Roles grant all custom status capabilities in Pattern Role'=>'تمنح الأدوار الإضافية المحددة نوعًا جميع قدرات الحالة المخصصة في نمط الدور.','For example, if the Author role has the edit_pitch_posts capability, a Supplemental Role of Page Author will include edit_pitch_pages'=>'على سبيل المثال، إذا كان دور المؤلف لديه قدرة edit_pitch_posts، فإن دورًا إضافيًا لمؤلف الصفحة سيشمل edit_pitch_pages.','define privacy types'=>'حدد أنواع الخصوصية','Subpage Vis.'=>'رؤية الصفحة الفرعية','existing sub-%s'=>'فرعي موجود - %s','Disabled Statuses:'=>'الحالات المعطلة:','Drop any status here to disable.'=>'ضع أي حالة هنا لتعطيلها.','License Key:'=>'مفتاح الترخيص:','Post Access'=>'الوصول إلى المنشور','Capability Requirements'=>'متطلبات القدرة','(Default Capabilities)'=>'(القدرات الافتراضية)','Custom Capabilities for this Status'=>'قدرات مخصصة لهذه الحالة','same as PARENT STATUS (%s)'=>'نفس حالة الوالد (%s)','same as %s status'=>'نفس حالة %s','Enforce status-specific capabilities, or share capabilities with another status.'=>'فرض القدرات المحددة حسب الحالة، أو مشاركة القدرات مع حالة أخرى.','List'=>'قائمة','Edit Others'=>'تعديل الآخرين','Delete Others'=>'حذف الآخرين','Revise'=>'مراجعة','Role can set posts to the "%s" status'=>'يمكن للدور تعيين المنشورات إلى حالة "%s"','Role can read "%s" posts'=>'يمكن للدور قراءة منشورات "%s"','Role sees uneditable "%s" posts in admin listing'=>'يمكن للدور رؤية منشورات "%s" غير القابلة للتعديل في قائمة الإدارة','Role can create revisions of "%s" posts'=>'يمكن للدور إنشاء مراجعات لمنشورات "%s"','Role can edit "%s" posts'=>'يمكن للدور تعديل منشورات "%s"','Role can edit other\'s "%s" posts'=>'يمكن للدور تعديل منشورات الآخرين "%s"','Role can delete "%s" posts'=>'يمكن للدور حذف منشورات "%s"','Role can delete other\'s "%s" posts'=>'يمكن للدور حذف منشورات الآخرين "%s"','Role Capabilities for "%s" status:'=>'قدرات الدور لحالة "%s":','Update Status'=>'تحديث الحالة','Edit basic role capabilities'=>'تعديل قدرات الدور الأساسية','Toggle all capabilities for this role'=>'تبديل جميع القدرات لهذا الدور','%s: assigned by Permission Group'=>'%s: المعين بواسطة مجموعة الأذونات','This capability is %s'=>'هذه القدرة هي %s','It is required in addition to the type-specific capability.'=>'مطلوب بالإضافة إلى القدرة الخاصة بالنوع.','Standard'=>'قياسي','Disabled'=>'معطل','Custom'=>'مخصص','Custom Read'=>'قراءة مخصصة','(same as %s)'=>'(نفس %s)','Toggle setting'=>'تبديل الإعداد','Edit Posts listing includes posts in this status (even if not editable)'=>'تعديل قائمة المنشورات تشمل المنشورات في هذه الحالة (حتى لو لم تكن قابلة للتحرير)','Can create revisions of posts in this status'=>'يمكن إنشاء مراجعات للمنشورات في هذه الحالة','Sorry, you do not have permission to edit custom statuses.'=>'عذراً، ليس لديك إذن لتعديل الحالات المخصصة.','same as %s'=>'نفس %s','Post Visibility'=>'رؤية المشاركة','Member'=>'عضو','Premium'=>'مميز','Staff'=>'موظف','Statuses enabled here are available as Visibility options for post publishing. Affected posts become inaccessable without a corresponding status-specific role assignment.'=>'الحالات المفعلة هنا متاحة كخيارات رؤية لنشر المشاركات. تصبح المشاركات المتأثرة غير قابلة للوصول بدون تعيين دور محدد مرتبط بالحالة.','Statuses enabled here are available in the editor as additional steps between Draft and Published.'=>'الحالات المفعلة هنا متاحة في المحرر كخطوات إضافية بين المسودة والمنشور.','Statuses alter your content\'s accessibility by imposing additional capability requirements.'=>'تغير الحالات وصول محتواك من خلال فرض متطلبات قدرات إضافية.','Enable Custom Capabilities by toggling the link below status name. If enabled, non-Editors will need a corresponding %ssupplemental role%s to edit posts of that status.'=>'قم بتمكين القدرات المخصصة عن طريق تبديل الرابط أدناه اسم الحالة. إذا تم التمكين، سيحتاج المستخدمون غير المحررين إلى دور إضافي مطابق %ssupplemental role%s لتعديل المشاركات بتلك الحالة.','For post edit by a user who cannot publish, %sworkflow is configured%s to make the Publish button increment the post to the next workflow status permitted.'=>'لتحرير المشاركة بواسطة مستخدم لا يمكنه النشر، تم تكوين %sworkflow%s لجعل زر النشر يزيد من حالة المشاركة إلى حالة سير العمل التالية المسموح بها.','For post edit by a user who cannot publish, %sworkflow is configured%s to make the Publish button escalate the post to the highest-ordered workflow status permitted.'=>'لتحرير المشاركة بواسطة مستخدم لا يمكنه النشر، تم تكوين %sworkflow%s لجعل زر النشر يرفع حالة المشاركة إلى أعلى حالة سير العمل المسموح بها.','For post edit by a user who cannot publish, the Publish button will escalate the post to the highest-order status permitted to the user.'=>'لتحرير المشاركة بواسطة مستخدم لا يمكنه النشر، سيؤدي زر النشر إلى رفع حالة المشاركة إلى أعلى حالة مسموح بها للمستخدم.','Please enable the PublishPress %sStatuses feature%s.'=>'يرجى تمكين ميزة %sStatuses%s في PublishPress.','Note that the Post Type itself will also need to have %sPermissions%s enabled.'=>'لاحظ أن نوع المشاركة نفسه سيحتاج أيضًا إلى تمكين %sPermissions%s.','To disable custom visibility statuses, first re-assign posts to a different status.'=>'لإيقاف تشغيل حالات الرؤية المخصصة، يجب أولاً إعادة تعيين المشاركات إلى حالة مختلفة.','Note, this only applies if the role definition includes the pp_moderate_any capability'=>'لاحظ، أن هذا ينطبق فقط إذا كانت تعريفات الأدوار تتضمن القدرة pp_moderate_any.','Create or edit custom Privacy or Workflow statuses.'=>'إنشاء أو تعديل حالات الخصوصية أو سير العمل المخصصة.','Create or edit custom Privacy statuses.'=>'إنشاء أو تعديل حالات الخصوصية المخصصة.','Extra Roles created as a type-specific copy of this role will enable assignment of specified custom statuses.'=>'الأدوار الإضافية التي تم إنشاؤها كنسخة محددة من هذه الدور ستسمح بتعيين حالات مخصصة محددة.','Editors do not need status-specific editing capabilities for workflow posts (Assigned, In Progress, Approved).'=>'لا يحتاج المحررون إلى قدرات تحرير محددة للحالات لمشاركات سير العمل (مخصصة، قيد التقدم، معتمدة).','If enabled, non-Editors will need to be granted editing access via the "Permissions" screen.'=>'إذا تم التمكين، سيحتاج المستخدمون غير المحررين إلى منحهم حق الوصول إلى التحرير عبر شاشة "الأذونات".','If enabled, a Visibility Status dropdown will appear in Quick Edit for easy status assignment.'=>'إذا تم التمكين، ستظهر قائمة منسدلة لحالة الرؤية في التحرير السريع لتسهيل تعيين الحالة.','If enabled, this will add Visibility Statuses support to the PublishPress Status plugin.'=>'إذا تم التمكين، سيضيف هذا دعم حالات الرؤية إلى إضافة PublishPress Status.','Default Capabilities'=>'القدرات الافتراضية','Revision'=>'مراجعة','Same as PARENT STATUS (%s)'=>'نفس حالة الوالد (%s)','Same as %s status'=>'نفس حالة %s','(Same as %s)'=>'(نفس %s)','Same as %s'=>'نفس %s','Search roles...'=>'بحث عن الأدوار...','restriction_attributeSub%1$s %2$s: '=>'Sub%1$s %2$s: ']];